        if (Platform.OS === 'android') {
			this.checkInstaller();

			this.boundWiredHeadsetDetect = this._wiredHeadsetDetect.bind(this);
			DeviceEventEmitter.addListener('WiredHeadset', this.boundWiredHeadsetDetect);

			DeviceEventEmitter.addListener('ShareIntentReceived',
				payload => {
					this.handleAndroidShare(payload)
				  // route to contacts, parse link, etc
				}
			  );

			// Warm-start deep-link fast path. MainActivity.handleViewIntent
			// emits this synchronously when the user taps a sylk://
			// notification while the app is already running. Bypasses
			// react-native-linking's AppState-lifecycle-gated 'url' event
			// (which has been measured at ~3 s wall-clock latency in
			// field traces — "Deep link received" native at 14:03:36 vs
			// JS "Event from url" at 14:03:39). The Linking listener
			// installed in componentDidMount still fires later as a
			// belt-and-suspenders fallback; eventFromUrl is idempotent
			// for the message branch (selectChatContact + setState are
			// no-ops on the same uri).
			DeviceEventEmitter.addListener('SylkDeepLink',
				(payload) => {
					const _url = payload && payload.url;
					if (!_url) return;
					utils.timestampedLog('[app] SylkDeepLink received url=', _url);
					try {
						this.eventFromUrl(_url);
					} catch (e) {
						console.log('[app] SylkDeepLink eventFromUrl threw', e && e.message);
					}
				}
			);

			// Bluetooth-headset redial hotkey (warm start).
			// MainActivity.emitVoiceCommandIntent forwards the
			// ACTION_VOICE_COMMAND / VOICE_SEARCH_HANDSFREE intent —
			// a long-press on the call button of an HFP headset such
			// as the Plantronics Voyager — as this event while the
			// app is running. Redial the last dialed URI immediately.
			// (Cold start goes through the pendingVoiceCommandTs
			// SharedPreferences stamp consumed in the constructor.)
			DeviceEventEmitter.addListener('SylkVoiceCommand',
				(payload) => {
					utils.timestampedLog('[headset-redial] voice command event, source=',
						(payload && payload.source) || 'unknown');
					try {
						this.headsetRedial('voice-command');
					} catch (e) {
						console.log('[headset-redial] headsetRedial threw', e && e.message);
					}
				}
			);

			// Dismiss the "Answering call..." fullscreen overlay the
			// moment AudioCallBox.componentDidMount fires for any call.
			// The overlay was painted on press to mask the ~1 s RN
			// mount latency between accept and the real call screen;
			// once the real screen is up, hand off without a
			// perceptible gap. The 8 s safety timer set on press is
			// a backstop in case AudioCallBox never mounts (e.g. the
			// call was rejected mid-transition).
			DeviceEventEmitter.addListener('SylkAudioCallBoxMounted',
				(payload) => {
					if (this.state.answeringCallOverlayUUID) {
						utils.timestampedLog('[call] [ui] call_id='
							+ (payload && payload.call_id || '?'),
							'overlay_dismissed_on_mount');
						this.setState({answeringCallOverlayUUID: null});
					}
					if (this._answeringOverlayTimer) {
						clearTimeout(this._answeringOverlayTimer);
						this._answeringOverlayTimer = null;
					}
				});
        }

		// A screen share ended from OUTSIDE the app — the Android system cast
		// pill, or iOS Control Center. Starting a share navigates the sharer to
		// the chat (so the peer sees the conversation rather than a mirror of
		// their own video), which means the call screen is unmounted by the time
		// the share stops. Route back to it: with nothing left to present, the
		// call UI is where the controls are. VideoBox stamps the pre-share
		// camera on the call object and reads it back on mount.
		//
		// Registered for both platforms (not just Android) — iOS Control Center
		// stop takes the same path. goBackToCall() no-ops when there is no
		// active call, so a share that ended because the CALL ended can't strand
		// the user on the call screen.
		DeviceEventEmitter.addListener('sylkScreenShareStopped', () => {
			if (this.currentRoute === '/call') return;
			utils.timestampedLog('[screen-share] stopped outside the app — returning to the call screen');
			try { this.goBackToCall(); } catch (e) { /* noop */ }
		});

		DarkModeManager.addListener((isDark) => {
		    this.onDarkModeChanged(isDark); // optional callback
		});

