	async fetchSharedItemsiOS() {
		if (Platform.OS !== 'ios') {
			return;
		} 

		// A share flow is already on screen -- don't stack another one
		// on top of it. Same guard handleAndroidShare() has always had;
		// this path never got it, and it runs on EVERY foreground.
		if (this.state.shareToContacts) {
			return;
		}

	    console.log('---fetchSharedItemsiOS');
	    //this.purgeSharedFiles();

		  // Restore the consumed markers once per session, before the
		  // first scan, so files imported before a restart aren't
		  // offered again.
		  await this._loadConsumedSharedFiles();

		  // 1. Get the App Group container path
		  const appGroupPath = await SharedDataModule.appGroupContainerPath();
		  
		  const sharedFiles = await this.getSharedFiles();
		  if (sharedFiles.length === 0) {
			  //console.log('No shared files');
			  return;
		  }

		  // Mark BEFORE handing them on: _startShareToContacts sets
		  // state and may change route, and another foreground can land
		  // while the user is still choosing recipients.
		  this._markSharedFilesConsumed(sharedFiles);

		  //console.log('Shared container:', appGroupPath);
		  sharedFiles.forEach((file) => {
		      file.filePath = file.path; 
		      file.fileName = file.name;
		      file.mimeType = mime.lookup(file.name); 
		      //console.log(file);
		  });

 		    console.log('Share', sharedFiles.length, 'items');

			this._startShareToContacts(sharedFiles);

			let what = 'Share text with contacts';
			let item = sharedFiles[0];
			if (item.weblink) {
				what = 'Share web link with contacts';
			}

			if (item.path) {
				what = 'Share file with contacts';
			}
			

			this._notificationCenter.postSystemNotification(what);
		  
	  }
  
	  startWatchingNetwork() {
		// Avoid duplicate listeners
		if (this.unsubscribeNetInfo) return;

		this.unsubscribeNetInfo = NetInfo.addEventListener((state) => {
		  const isConnected = state.isConnected === true;
		  const wasConnected = this._wasConnected;
		  this._wasConnected = isConnected;

		  // Cache reachability for the live-share watchdog. `isInternetReachable`
		  // is tri-state (true / false / null while probing); only an explicit
		  // false means "the platform knows there is no path", which is the one
		  // case where nudging the socket is guaranteed to fail.
		  this._netReachable = isConnected && state.isInternetReachable !== false;

		  const isWifi = state.type === "wifi";
		  const isMobile = state.type === "cellular";

		  //console.log("Network changed:", state.type, "connected:", state.isConnected);

		  if (isWifi) {
	         this.setState({connectivity: 'wifi'});

			//console.log("Connected via Wi-Fi");
			this.onWifi();
		  } else if (isMobile) {
			//console.log("Connected via Mobile Data");
			this.setState({connectivity: 'mobile'});
			this.onMobile();
		  }

		  // Connectivity just transitioned false -> true. If the server
		  // configuration never made it down at boot (DNS timed out,
		  // no cache), retry now that the network is clearly up. This
		  // is what prevents test numbers from being missing forever
		  // on a cold-boot-offline fresh install.
		  if (isConnected && wasConnected === false) {
			this.maybeRetryServerConfiguration('network-restored');
			// A location share running through an outage has been standing down
			// (see the watchdog). This transition is what ends the dark period:
			// reconnect right now instead of waiting up to 30s for the next tick.
			this._forceReconnectForShares('network-restored');
		  }
		});
	  }

	  // Retry downloadSylkConfiguration() if we never managed to load
	  // the per-server config at startup. Guarded by an in-flight flag
	  // and an empty-testNumbers check so it's safe to call from any
	  // recovery hook (NetInfo, WSS reconnect, manual retry button).
	  maybeRetryServerConfiguration(reason) {
		const hasTestNumbers = Array.isArray(this.state.testNumbers)
		                       && this.state.testNumbers.length > 0;
		if (hasTestNumbers) return;
		if (!this.state.configurationUrl) return;
		if (!this.state.defaultDomain) return;
		if (this._configRetryInFlight) return;

		utils.timestampedLog('[config] retry triggered (reason:', reason + ')',
		                     this.state.configurationUrl);
		this._configRetryInFlight = true;
		this.downloadSylkConfiguration(this.state.defaultDomain, this.state.configurationUrl)
		    .catch((e) => {
		        console.log('[config] retry failed:', e);
		        utils.timestampedLog('[config] retry failed:',
		                             e && e.message ? e.message : String(e));
		    })
		    .finally(() => {
		        this._configRetryInFlight = false;
		    });
	  }

	  // Unconditional server-config refresh, fired on EVERY sign-in.
	  // Unlike maybeRetryServerConfiguration() this does NOT bail when a
	  // cached config exists: the cache may predate server-side capability
	  // changes (e.g. addressBookServer appearing in sylk-config.json).
	  // downloadSylkConfiguration() diffs against the cache, applies via
	  // initConfiguration() and re-persists, so repeated calls are cheap and
	  // safe. Shares the in-flight flag with the retry path. Fire-and-forget.
	  refreshServerConfiguration(reason) {
		const domain = this.state.sylkDomain || this.state.defaultDomain;
		if (!domain) return;
		if (this._configRetryInFlight) return;

		const url = this.state.configurationUrl || ('https://' + domain + '/sylk-config.json');
		utils.timestampedLog('[config] sign-in refresh (reason:', reason + ')', url);
		this._configRetryInFlight = true;
		this.downloadSylkConfiguration(domain, url)
		    .catch((e) => {
		        console.log('[config] sign-in refresh failed:', e);
		        utils.timestampedLog('[config] sign-in refresh failed:',
		                             e && e.message ? e.message : String(e));
		    })
		    .finally(() => {
		        this._configRetryInFlight = false;
		    });
	  }

	 stopWatchingNetwork() {
		if (this.unsubscribeNetInfo) {
		  this.unsubscribeNetInfo();
		  this.unsubscribeNetInfo = null;
		}
	  }
	
	  async getCurrentNetwork() {
		const state = await NetInfo.fetch();
		return {
		  isConnected: state.isConnected,
		  isWifi: state.type === "wifi",
		  isMobile: state.type === "cellular",
		  type: state.type,
		  details: state.details,
		};
	  }
	
