                    const _trimmed = _r.trim();
                    const _isPaymentRequired = /^payment required\b/i.test(_trimmed);
                    const _isRoutineEnd =
                        /^(call ended|hangup|busy|cancelled|canceled|no answer|terminated|bye|ok)\b/i.test(_trimmed);
